from __future__ import annotations

import tempfile
from pathlib import Path

from relocation_jobs.mcp.ports import _markdown_fragment_to_tex
from relocation_jobs.mcp.render import render_tex_to_pdf
from relocation_jobs.mcp.service import get_interview_note_detail, save_interview_note

_PREAMBLE = r"""\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage[T1]{fontenc}
\usepackage{lmodern}
\usepackage{enumitem}
\usepackage{titlesec}
\usepackage{xcolor}
\usepackage{hyperref}

\definecolor{accent}{RGB}{31,74,121}

\titleformat{\section}
  {\Large\bfseries\color{accent}}{\thesection}{0.6em}{}
  [{\color{accent}\titlerule}]
\titlespacing*{\section}{0pt}{2.2em}{1em}

\titleformat{\subsection}
  {\bfseries}{}{0pt}{}
\titlespacing*{\subsection}{0pt}{1.4em}{0.6em}

\renewcommand{\labelitemi}{\textcolor{accent}{\textbullet}}

\hypersetup{
  colorlinks=true,
  linkcolor=accent,
  bookmarksopen=true,
  pdftitle={Creative Fabrica HR Screening},
  pdfauthor={Interview Notes}
}

\title{\color{accent}Creative Fabrica --- HR Screening Round}
\author{Interview Notes}
\date{}

\begin{document}
\maketitle

"""


def to_full_tex(source: str) -> str:
    body = (source or "").strip()
    if r"\documentclass" in body:
        return body if body.endswith("\n") else body + "\n"
    if body.startswith("#"):
        body = _markdown_fragment_to_tex(body).strip()
    if body.startswith(r"\section*{Creative Fabrica"):
        lines = body.splitlines()
        body = "\n".join(lines[1:]).strip()
    return f"{_PREAMBLE}{body}\n\\end{{document}}\n"


def main() -> None:
    detail = get_interview_note_detail("creative-fabrica-hr-screen")
    tex = to_full_tex(detail["content"])
    out = Path("/tmp/creative-fabrica-hr-screen.tex")
    out.write_text(tex, encoding="utf-8")
    assert tex.startswith("\\documentclass")
    assert "##" not in tex
    assert r"\begin{document}" in tex
    assert r"\end{document}" in tex
    with tempfile.TemporaryDirectory() as tmp:
        tex_path = Path(tmp) / "amin_mortezaie_interview_creative_fabrica_hr_screen.tex"
        tex_path.write_text(tex, encoding="utf-8")
        compiled = render_tex_to_pdf(tex_path)
        print("COMPILE_OK", compiled.ok)
        if not compiled.ok:
            print(compiled.log[-2500:])
            raise SystemExit(1)
    saved = save_interview_note(
        "creative-fabrica-hr-screen",
        tex,
        label="Creative Fabrica — HR Screening Round",
    )
    print("SAVED", saved)
    print("FIRST_LINE", tex.splitlines()[0])
    print("CHARS", len(tex))


if __name__ == "__main__":
    main()
